// Every raster on the site comes through here. Files are generated by
// `npm run images` (scripts/prepare-images.mjs) as `{name}-{480,1280}w.webp`
// or, for project screenshots, `{slug}/{n}-{480,1280}w.webp` at 16:9.
// Vite globs them at build time, so they are hashed like any other asset.

const projectFiles = import.meta.glob('../assets/projects/*/*.webp', { eager: true, import: 'default' })
const naturalFiles = import.meta.glob('../assets/{credentials,figures}/*.webp', { eager: true, import: 'default' })

function variants(files, keyOf) {
  const out = {}
  for (const [path, url] of Object.entries(files)) {
    const m = keyOf(path)
    if (m) (out[m.key] ??= []).push({ width: m.width, url })
  }
  for (const k in out) out[k].sort((a, b) => a.width - b.width)
  return out
}

const shots = variants(projectFiles, (p) => {
  const m = p.match(/projects\/([^/]+)\/(\d+)-(\d+)w\.webp$/)
  return m && { key: `${m[1]}/${m[2]}`, width: Number(m[3]) }
})
const naturals = variants(naturalFiles, (p) => {
  const m = p.match(/\/([^/]+)-(\d+)w\.webp$/)
  return m && { key: m[1], width: Number(m[2]) }
})

const pack = (list, ratio) => {
  if (!list) throw new Error('Missing image: run `npm run images` and check the name')
  const largest = list[list.length - 1]
  return {
    src: largest.url,
    srcSet: list.map((v) => `${v.url} ${v.width}w`).join(', '),
    width: largest.width,
    height: Math.round(largest.width * ratio),
  }
}

/** A 16:9 project screenshot: screenshot('telco-churn', 1) */
export const screenshot = (slug, n) => pack(shots[`${slug}/${n}`], 9 / 16)

/**
 * A screenshot the pipeline kept whole (KEEP_WHOLE), with its real ratio.
 * Frames cover-crop these wide screens, magnifying them beyond what `sizes`
 * says, so only the largest file is offered.
 */
export const wholeScreenshot = (slug, n, ratio) => {
  const image = pack(shots[`${slug}/${n}`], ratio)
  return { ...image, srcSet: undefined }
}

/** A natural-ratio image from src/assets/credentials or src/assets/figures. */
export const natural = (name, ratio) => pack(naturals[name], ratio)
